// Overlap depths of the ball box against a brick, or null when they do not
// overlap. `collides()` keeps answering the boolean question; this answers
// HOW MUCH on each axis, which is what decides the face that was hit.
function overlapDepths(ball, brick) {
  const left = ball.x - ball.r;
  const right = ball.x + ball.r;
  const top = ball.y - ball.r;
  const bottom = ball.y + ball.r;
  if (right <= brick.x || left >= brick.x + brick.w || bottom <= brick.y || top >= brick.y + brick.h) {
    return null;
  }
  return {
    x: Math.min(right, brick.x + brick.w) - Math.max(left, brick.x),
    y: Math.min(bottom, brick.y + brick.h) - Math.max(top, brick.y),
  };
}

// Pushes the ball out of the brick on the horizontal axis, to the side it
// came from (its center side of the brick center).
function pushOutX(ball, brick) {
  const center = brick.x + brick.w / 2;
  ball.x = ball.x < center ? brick.x - ball.r : brick.x + brick.w + ball.r;
}

function pushOutY(ball, brick) {
  const center = brick.y + brick.h / 2;
  ball.y = ball.y < center ? brick.y - ball.r : brick.y + brick.h + ball.r;
}

