  const { ball } = state;
  let bouncedX = false;
  let bouncedY = false;
  let resolved = false;

  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    const depths = overlapDepths(ball, brick);
    if (!depths) continue;

    resolved = true;
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);

    if (Math.abs(depths.x - depths.y) <= EPS) {
      // Corner: equal penetration on both axes — both components invert.
      if (!bouncedX) { ball.vx = -ball.vx; pushOutX(ball, brick); bouncedX = true; }
      if (!bouncedY) { ball.vy = -ball.vy; pushOutY(ball, brick); bouncedY = true; }
    } else if (depths.x < depths.y) {
      if (!bouncedX) { ball.vx = -ball.vx; pushOutX(ball, brick); bouncedX = true; }
    } else {
      if (!bouncedY) { ball.vy = -ball.vy; pushOutY(ball, brick); bouncedY = true; }
    }
  }
  return resolved;
}
