function sweptHit(ball, prevX, prevY, brick) {
  const r = ball.r;
  const minX = brick.x - r;
  const maxX = brick.x + brick.w + r;
  const minY = brick.y - r;
  const maxY = brick.y + brick.h + r;
  const dx = ball.x - prevX;
  const dy = ball.y - prevY;

  let nearX = -Infinity, farX = Infinity;
  let nearY = -Infinity, farY = Infinity;

  if (dx === 0) {
    if (prevX <= minX || prevX >= maxX) return null;
  } else {
    const a = (minX - prevX) / dx;
    const b = (maxX - prevX) / dx;
    nearX = Math.min(a, b);
    farX = Math.max(a, b);
  }
  if (dy === 0) {
    if (prevY <= minY || prevY >= maxY) return null;
  } else {
    const a = (minY - prevY) / dy;
    const b = (maxY - prevY) / dy;
    nearY = Math.min(a, b);
    farY = Math.max(a, b);
  }

  const tEnter = Math.max(nearX, nearY, 0);
  const tExit = Math.min(farX, farY, 1);
  if (tEnter > tExit || tEnter > 1) return null;

  // The axis that brings the center into the expanded rectangle is the face
  // that was hit. Equal entry times = a corner: both axes are involved.
  if (nearX > nearY) return { t: tEnter, axis: 'x' };
  if (nearY > nearX) return { t: tEnter, axis: 'y' };
  return { t: tEnter, axis: 'both' };
}
