  }

  // Bricks: discrete resolution when the ball rests inside a brick, then a
  // swept pass so a fast ball cannot jump over a brick in one step (tunneling).
  if (!resolveBrickOverlaps(state) && !overlapsAnyLiveBrick(state, prevX, prevY)) {
    resolveBrickSweep(state, prevX, prevY);
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

// --- Brick collision resolution (was mixed into frame(); see debt #2) ------

// Breaks every live brick the ball overlaps, scores it, and bounces the ball
// out of the overlap: the axis with the smallest penetration is the face that
// was hit. Returns true when at least one brick was resolved.
function resolveBrickOverlaps(state) {
  const { ball } = state;
  let resolved = false;

  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    const depths = overlapDepths(ball, brick);
    if (!depths) continue;

    resolved = true;
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);

    if (depths.x < depths.y) {
      ball.vx = -ball.vx;
    } else {
      ball.vy = -ball.vy;
    }
  }
  return resolved;
}

// Overlap depths of the ball box against a brick on each axis, or null when
// they do not overlap. `collides()` answers the boolean question; this answers
// HOW MUCH, which is what decides which face was hit.
function overlapDepths(ball, brick) {
  const left = ball.x - ball.r;
  const right = ball.x + ball.r;
  const top = ball.y - ball.r;
  const bottom = ball.y + ball.r;
  if (
    right <= brick.x ||
    left >= brick.x + brick.w ||
    bottom <= brick.y ||
    top >= brick.y + brick.h
  ) {
    return null;
  }
  return {
    x: Math.min(right, brick.x + brick.w) - Math.max(left, brick.x),
    y: Math.min(bottom, brick.y + brick.h) - Math.max(top, brick.y),
  };
}

