    if (!brick.alive) continue;
    const depths = overlapDepths(ball, brick);
    if (!depths) continue;

    resolved = true;
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);

    if (depths.x < depths.y - EPS) {
      if (!bouncedX) {
        ball.vx = -ball.vx;
        pushOutX(ball, brick);
        bouncedX = true;
      }
    } else if (depths.y < depths.x - EPS) {
      if (!bouncedY) {
        ball.vy = -ball.vy;
        pushOutY(ball, brick);
        bouncedY = true;
      }
    } else {
      // Corner: equal penetration on both axes — the ball arrived on the
      // diagonal, so both components invert.
      if (!bouncedX) {
        ball.vx = -ball.vx;
        pushOutX(ball, brick);
        bouncedX = true;
      }
      if (!bouncedY) {
        ball.vy = -ball.vy;
        pushOutY(ball, brick);
        bouncedY = true;
      }
    }
  }
  return resolved;
}

