// Swept AABB pass (Minkowski sum): expands every brick by the ball radius and
// casts the ball-center segment from the previous position to the current one
// against the expanded rectangle. Detects a crossing that a discrete test at
// the two endpoints never sees (tunneling). Placed last: runs only when the
// ball overlaps no brick at rest, so it cannot double-count a discrete bounce.
function resolveBrickSweep(state, prevX, prevY) {
  const { ball } = state;

  let best = null;
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    const hit = sweptHit(ball, prevX, prevY, brick);
    if (hit && (!best || hit.t < best.t)) best = { brick, ...hit };
  }
  if (!best) return;

  // Move the ball to the touch point (its center on the expanded-rectangle
  // boundary: the ball merely touches the face it hit mid-flight).
  ball.x = prevX + (ball.x - prevX) * best.t;
  ball.y = prevY + (ball.y - prevY) * best.t;

  best.brick.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(best.brick, state.combo);

  if (best.axis === 'x') {
    ball.vx = -ball.vx;
  } else if (best.axis === 'y') {
    ball.vy = -ball.vy;
  } else {
    // Corner entry: the center enters the expanded rectangle through both
    // edges at the same time — both components invert.
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
  }
}

// Time of impact of the ball-center segment against the brick expanded by the
// ball radius, via the slab method (noonat: AABB vs segment). Returns null
// when the segment never enters the expanded rectangle, or the entry time t in
// [0, 1] together with the axis whose slab edge the center crosses first.
function sweptHit(ball, prevX, prevY, brick) {
  const r = ball.r;
  const minX = brick.x - r;
  const maxX = brick.x + brick.w + r;
  const minY = brick.y - r;
  const maxY = brick.y + brick.h + r;
  const dx = ball.x - prevX;
  const dy = ball.y - prevY;

  let nearX = -Infinity;
  let farX = Infinity;
  let nearY = -Infinity;
  let farY = Infinity;

  if (dx === 0) {
    if (prevX <= minX || prevX >= maxX) return null;
  } else {
    const a = (minX - prevX) / dx;
    const b = (maxX - prevX) / dx;
    nearX = Math.min(a, b);
    farX = Math.max(a, b);
  }
  if (dy === 0) {
    if (prevY <= minY || prevY >= maxY) return null;
  } else {
    const a = (minY - prevY) / dy;
    const b = (maxY - prevY) / dy;
    nearY = Math.min(a, b);
    farY = Math.max(a, b);
  }

  const tEnter = Math.max(nearX, nearY, 0);
  const tExit = Math.min(farX, farY, 1);
  if (tEnter > tExit || tEnter > 1) return null;

  if (nearX > nearY + EPS) return { t: tEnter, axis: 'x' };
  if (nearY > nearX + EPS) return { t: tEnter, axis: 'y' };
  return { t: tEnter, axis: 'both' };
}

